'use client'

import type { ComponentType } from 'react'

import { DesignedForFocusIllustration } from './content-section-one-designed-for-focus-illustration'
import { FastByDefaultIllustration } from './content-section-one-fast-by-default-illustration'
import { FlexibleAtScaleIllustration } from './content-section-one-flexible-at-scale-illustration'

type Principle = {
  title: string
  description: string
  illustration: ComponentType
}

const principles: readonly Principle[] = [
  {
    title: 'Fast by default',
    description: 'Common actions stay immediate, predictable, and close to where work happens.',
    illustration: FastByDefaultIllustration,
  },
  {
    title: 'Designed for focus',
    description: 'Clear hierarchy and restrained interfaces keep attention on the current task.',
    illustration: DesignedForFocusIllustration,
  },
  {
    title: 'Flexible at scale',
    description: 'Start with simple workflows and add structure as your product and team evolve.',
    illustration: FlexibleAtScaleIllustration,
  },
]

export default function ContentSectionOne() {
  return (
    <section className="overflow-hidden py-16 text-foreground md:py-24">
      <div className="mx-auto max-w-6xl px-5 sm:px-8">
        <div className="grid gap-8 pb-12 md:grid-cols-[1fr_0.7fr] md:items-end md:border-b">
          <h2 className="max-w-3xl text-3xl font-semibold tracking-tighter text-balance sm:text-4xl lg:text-5xl">
            Software should remove friction, not create more of it.
          </h2>

          <p className="max-w-md text-base leading-7 text-muted-foreground md:justify-self-end">
            Every interaction is designed to make complex workflows feel direct, calm, and
            understandable.
          </p>
        </div>

        <div className="-mx-5 [scrollbar-width:none] overflow-x-auto px-5 pt-8 pb-2 sm:-mx-8 sm:px-8 md:mx-0 md:overflow-visible md:px-0 md:pt-0 md:pb-0 [&::-webkit-scrollbar]:hidden">
          <div className="flex w-max gap-4 md:grid md:w-full md:grid-cols-3 md:gap-0 md:border-b">
            {principles.map((principle, index) => {
              const Illustration = principle.illustration

              return (
                <article
                  key={principle.title}
                  className={[
                    'w-[min(82vw,20rem)] shrink-0 rounded-lg border bg-card',
                    'md:w-auto md:rounded-none md:border-0 md:bg-transparent',
                    index > 0 ? 'md:border-l' : '',
                  ].join(' ')}
                >
                  <div className="relative flex min-h-52 items-center justify-center overflow-hidden">
                    <Illustration />

                    <span className="absolute top-5 right-5 font-mono text-xs text-muted-foreground">
                      0{index + 1}
                    </span>
                  </div>

                  <div className="p-6 md:px-7 md:py-8">
                    <h3 className="text-lg font-medium tracking-tight">{principle.title}</h3>

                    <p className="mt-3 max-w-sm text-sm leading-6 text-muted-foreground">
                      {principle.description}
                    </p>
                  </div>
                </article>
              )
            })}
          </div>
        </div>
      </div>
    </section>
  )
}

'use client'

import { useState } from 'react'
import { motion, useReducedMotion } from 'motion/react'

const FOCUS_DURATION = 3.6

const FOCUS_TIMES = [0, 0.12, 0.34, 0.48, 0.68, 0.8, 0.89, 0.94, 1]

const focusCircles = [
  {
    id: 'outer',
    initialX: -44,
    initialOpacity: 0.48,
    focusScale: 1.42,
    focusOpacity: 0.62,
  },
  {
    id: 'middle',
    initialX: 0,
    initialOpacity: 0.38,
    focusScale: 0.9,
    focusOpacity: 0,
  },
  {
    id: 'inner',
    initialX: 44,
    initialOpacity: 0.48,
    focusScale: 0.56,
    focusOpacity: 1,
  },
] as const

export function DesignedForFocusIllustration() {
  const reduceMotion = useReducedMotion() ?? false
  const [isHovered, setIsHovered] = useState(false)

  const shouldAnimate = isHovered && !reduceMotion

  return (
    <div
      aria-hidden="true"
      className="relative h-45 w-full overflow-hidden md:h-60"
      onPointerEnter={() => setIsHovered(true)}
      onPointerLeave={() => setIsHovered(false)}
    >
      <motion.div
        className="absolute inset-0 flex items-center justify-center"
        initial={false}
        animate={
          shouldAnimate
            ? {
                opacity: [1, 1, 1, 1, 1, 1, 0, 0, 1],
                filter: [
                  'blur(0px)',
                  'blur(0px)',
                  'blur(0px)',
                  'blur(0px)',
                  'blur(0px)',
                  'blur(0px)',
                  'blur(8px)',
                  'blur(8px)',
                  'blur(0px)',
                ],
                scale: [1, 1, 1, 1, 1, 1, 0.94, 0.94, 1],
              }
            : {
                opacity: 1,
                filter: 'blur(0px)',
                scale: 1,
              }
        }
        transition={
          shouldAnimate
            ? {
                duration: FOCUS_DURATION,
                times: FOCUS_TIMES,
                ease: 'easeInOut',
                repeat: Infinity,
                repeatDelay: 0.08,
              }
            : {
                duration: 0.4,
                ease: [0.22, 1, 0.36, 1],
              }
        }
      >
        {focusCircles.map((circle) => (
          <motion.span
            key={circle.id}
            className="absolute size-22 rounded-full border border-foreground/60"
            initial={false}
            animate={
              shouldAnimate
                ? {
                    x: [
                      circle.initialX,
                      circle.initialX,
                      0,
                      0,
                      0,
                      0,
                      0,
                      circle.initialX,
                      circle.initialX,
                    ],
                    scale: [1, 1, 1, 1, circle.focusScale, circle.focusScale, 0.9, 1, 1],
                    opacity: [
                      circle.initialOpacity,
                      circle.initialOpacity,
                      0.82,
                      1,
                      circle.focusOpacity,
                      circle.focusOpacity,
                      0,
                      circle.initialOpacity,
                      circle.initialOpacity,
                    ],
                  }
                : {
                    x: circle.initialX,
                    scale: 1,
                    opacity: circle.initialOpacity,
                  }
            }
            transition={
              shouldAnimate
                ? {
                    duration: FOCUS_DURATION,
                    times: FOCUS_TIMES,
                    ease: [0.22, 1, 0.36, 1],
                    repeat: Infinity,
                    repeatDelay: 0.08,
                  }
                : {
                    duration: 0.45,
                    ease: [0.22, 1, 0.36, 1],
                  }
            }
          />
        ))}
      </motion.div>
    </div>
  )
}

export default DesignedForFocusIllustration

'use client'

import { useState } from 'react'
import { motion, useReducedMotion } from 'motion/react'

const SPEED_LINE_COUNT = 13

const speedLines = Array.from({ length: SPEED_LINE_COUNT }, (_, index) => {
  const center = (SPEED_LINE_COUNT - 1) / 2
  const distanceFromCenter = Math.abs(index - center) / center

  return {
    y: 34 + index * 7.7,
    start: 47 + distanceFromCenter * 16 + Math.sin(index * 1.25) * 7,
    end: 254 - distanceFromCenter * 23 + Math.cos(index * 0.85) * 7,
    thickness: 1.15 + (1 - distanceFromCenter) * 0.45,
    opacity: 0.4 + (1 - distanceFromCenter) * 0.55,
    direction: index <= center ? 1 : -1,
    travel: 8 + (1 - distanceFromCenter) * 9,
  }
})

function createSpeedLinePath({
  start,
  end,
  y,
  thickness,
}: {
  start: number
  end: number
  y: number
  thickness: number
}) {
  const taperLength = 12
  const roundedEnd = 4

  return [
    `M ${start} ${y}`,
    `L ${start + taperLength} ${y - thickness}`,
    `L ${end - roundedEnd} ${y - thickness}`,
    `Q ${end} ${y - thickness} ${end} ${y}`,
    `Q ${end} ${y + thickness} ${end - roundedEnd} ${y + thickness}`,
    `L ${start + taperLength} ${y + thickness}`,
    'Z',
  ].join(' ')
}

export function FastByDefaultIllustration() {
  const reduceMotion = useReducedMotion() ?? false
  const [isHovered, setIsHovered] = useState(false)

  return (
    <div
      aria-hidden="true"
      className="relative h-45 w-full overflow-hidden md:h-60"
      onPointerEnter={() => {
        if (!reduceMotion) setIsHovered(true)
      }}
      onPointerLeave={() => {
        if (!reduceMotion) setIsHovered(false)
      }}
    >
      <svg
        className="absolute inset-0 size-full overflow-visible text-foreground"
        viewBox="0 0 300 160"
        fill="none"
        preserveAspectRatio="xMidYMid meet"
      >
        <defs>
          <clipPath id="speed-lines-clip">
            <rect x="34" y="20" width="232" height="120" rx="8" />
          </clipPath>
        </defs>
        <g clipPath="url(#speed-lines-clip)">
          {speedLines.map((line, index) => {
            const path = createSpeedLinePath(line)
            const travel = line.travel * line.direction

            return (
              <motion.path
                key={index}
                d={path}
                fill="currentColor"
                initial={false}
                animate={
                  isHovered && !reduceMotion
                    ? {
                        x: [0, travel, travel * 0.25, travel * -0.65, 0],
                        opacity: [
                          line.opacity,
                          Math.min(line.opacity + 0.25, 1),
                          line.opacity,
                          Math.max(line.opacity - 0.14, 0.25),
                          line.opacity,
                        ],
                      }
                    : {
                        x: 0,
                        opacity: line.opacity,
                      }
                }
                transition={
                  isHovered && !reduceMotion
                    ? {
                        duration: 0.9 + index * 0.025,
                        delay: index * 0.025,
                        ease: 'easeInOut',
                        repeat: Infinity,
                      }
                    : {
                        duration: 0.35,
                        ease: [0.22, 1, 0.36, 1],
                      }
                }
              />
            )
          })}
        </g>
      </svg>

      <div className="pointer-events-none absolute inset-y-[18%] left-0 w-16 bg-linear-to-r to-transparent" />
      <div className="pointer-events-none absolute inset-y-[18%] right-0 w-16 bg-linear-to-l to-transparent" />
    </div>
  )
}

export default FastByDefaultIllustration

'use client'

import type { PointerEvent } from 'react'
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  type MotionValue,
} from 'motion/react'

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max)

const FLEXIBLE_LINE_COUNT = 17

const flexibleLines = Array.from({ length: FLEXIBLE_LINE_COUNT }, (_, index) => {
  const progress = index / (FLEXIBLE_LINE_COUNT - 1)

  // outer lines away from the illustration edges.
  return 0.04 + progress * 0.92
})

type FlexibleLineProps = {
  position: number
  pointerX: MotionValue<number>
  interaction: MotionValue<number>
  reduceMotion: boolean
}

function FlexibleLine({ position, pointerX, interaction, reduceMotion }: FlexibleLineProps) {
  const influence = useTransform(() => {
    if (reduceMotion) return 0

    const distance = pointerX.get() - position
    const influenceRadius = 0.17

    return Math.exp(-Math.pow(distance / influenceRadius, 2))
  })

  const left = useTransform(() => {
    if (reduceMotion) {
      return `${position * 100}%`
    }

    const pointer = pointerX.get()
    const amount = interaction.get()
    const distance = pointer - position
    const strength = influence.get()

    const flexiblePosition = position + distance * strength * amount * 0.88

    return `${clamp(flexiblePosition, 0.02, 0.98) * 100}%`
  })

  const opacity = useTransform(() => {
    if (reduceMotion) return 0.24

    const amount = interaction.get()
    const strength = influence.get()

    return 0.2 + amount * (0.08 + strength * 0.72)
  })

  const scaleY = useTransform(() => {
    if (reduceMotion) return 1

    return 1 + interaction.get() * influence.get() * 0.16
  })

  const scaleX = useTransform(() => {
    if (reduceMotion) return 1

    return 1 + interaction.get() * influence.get() * 0.65
  })

  return (
    <motion.span
      className="absolute inset-y-[16%] w-px origin-center bg-foreground"
      style={{
        left,
        x: '-50%',
        opacity,
        scaleX,
        scaleY,
      }}
    />
  )
}

export function FlexibleAtScaleIllustration() {
  const reduceMotion = useReducedMotion() ?? false

  const rawPointerX = useMotionValue(0.5)
  const rawInteraction = useMotionValue(0)

  const pointerX = useSpring(rawPointerX, {
    stiffness: 280,
    damping: 30,
    mass: 0.35,
  })

  const interaction = useSpring(rawInteraction, {
    stiffness: 220,
    damping: 24,
    mass: 0.4,
  })

  const updatePointerPosition = (event: PointerEvent<HTMLDivElement>) => {
    if (reduceMotion) return

    const bounds = event.currentTarget.getBoundingClientRect()
    const localX = event.clientX - bounds.left
    const normalizedX = localX / bounds.width

    rawPointerX.set(clamp(normalizedX, 0.03, 0.97))
  }

  const handlePointerEnter = (event: PointerEvent<HTMLDivElement>) => {
    if (reduceMotion) return

    updatePointerPosition(event)
    rawInteraction.set(1)
  }

  const handlePointerLeave = () => {
    if (reduceMotion) return

    rawInteraction.set(0)
  }

  return (
    <div
      aria-hidden="true"
      className="relative h-45 w-full overflow-hidden md:h-60"
      onPointerEnter={handlePointerEnter}
      onPointerMove={updatePointerPosition}
      onPointerLeave={handlePointerLeave}
    >
      {flexibleLines.map((position, index) => (
        <FlexibleLine
          key={index}
          position={position}
          pointerX={pointerX}
          interaction={interaction}
          reduceMotion={reduceMotion}
        />
      ))}
    </div>
  )
}

export default FlexibleAtScaleIllustration
